const $=id=>document.getElementById(id);
const state={selected:'earth',view:'earth',time:Date.now(),speed:3600,direction:1,playing:!matchMedia('(prefers-reduced-motion: reduce)').matches,trueScale:false,orbits:true,labels:true,atmospheres:true,cosmicYears:0,cosmicSpeed:2000000,follow:'galaxy'};
