const scene=new THREE.Scene();scene.background=new THREE.Color(0x05090e);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.001,50000);
let renderer;
try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,logarithmicDepthBuffer:true});}catch(error){$('loading').innerHTML='<span>Your browser could not start the 3D view.</span><small>Enable hardware acceleration or open this page in a WebGL 2 browser.</small>';throw error;}
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
$('space').append(renderer.domElement);
