 if(body.id==='venus')axis.add(atmosphere(0xe2ba79,1.025));if(body.id==='neptune')axis.add(atmosphere(0x5f94ff,1.015));
 if(body.id==='sun'){const glowCanvas=document.createElement('canvas');glowCanvas.width=128;glowCanvas.height=128;const ctx=glowCanvas.getContext('2d');const gradient=ctx.createRadialGradient(64,64,8,64,64,64);gradient.addColorStop(0,'rgba(255,192,78,.65)');gradient.addColorStop(.28,'rgba(255,150,45,.14)');gradient.addColorStop(1,'rgba(255,110,15,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,128,128);const glow=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(glowCanvas),transparent:true,blending:THREE.AdditiveBlending,depthWrite:false}));glow.scale.set(6,6,1);axis.add(glow);axis.add(atmosphere(0xffbf60,1.025));}
