let last=performance.now(),lastUI=0;const previousTarget=new THREE.Vector3();
function animate(){requestAnimationFrame(animate);const now=performance.now(),dt=(now-last)/1000;last=now;if(!ready)return;if(isGalactic()){animateGalaxy(now,dt);return;}previousTarget.copy(planetObjects[state.selected].group.position);if(state.playing){state.time+=dt*state.speed*1000*state.direction;if(state.time<MIN_TIME||state.time>MAX_TIME){state.time=Math.max(MIN_TIME,Math.min(MAX_TIME,state.time));state.playing=false;syncPlayback();toast('Reached the orbital model’s date limit (1800–2050).');}}
 updatePositions();if(Math.abs(state.time-lastOrbitTime)>DAY)createOrbits();if(transition){const t=Math.min(1,(now-transition.start)/1600),ease=1-Math.pow(1-t,3);const d=cameraDestination();camera.position.lerpVectors(transition.position,d.target.clone().add(d.offset),ease);controls.target.lerpVectors(transition.target,d.target,ease);if(t===1)transition=null;}else if(state.view==='earth'||state.view==='body'){const delta=planetObjects[state.selected].group.position.clone().sub(previousTarget);camera.position.add(delta);controls.target.add(delta);}
 for(const {shader,occluderId} of eclipseShaders){shader.uniforms.eclipseCenter.value.copy(planetObjects[occluderId].group.position);shader.uniforms.eclipseRadius.value=radius(bodies.find(b=>b.id===occluderId));shader.uniforms.solarRadius.value=radius(bodies[0]);}stars.position.copy(camera.position);controls.update();renderer.render(scene,camera);updateLabels();if(now-lastUI>150){if(state.view==='earth'||state.view==='body'){const b=bodies.find(b=>b.id===state.selected);if(b.id==='moon')$('distance').innerHTML=(new THREE.Vector3(...moonRelativeAU(state.time)).length()*AU_KM).toLocaleString('en-US',{maximumFractionDigits:0})+' <small>km</small>';else if(b.id!=='sun')$('distance').innerHTML=new THREE.Vector3(...planetObjects[b.id].raw).length().toFixed(2)+' <small>AU</small>';}const date=new Date(state.time);if(document.activeElement!==$('date'))$('date').value=date.toISOString().slice(0,10);$('clock-time').textContent=date.toISOString().slice(11,19);lastUI=now;}
}
function animateGalaxy(now,dt){
 const before=galaxyView.target(state.follow);
 if(state.playing){state.cosmicYears+=dt*state.cosmicSpeed*state.direction;if(Math.abs(state.cosmicYears)>COSMIC_LIMIT){state.cosmicYears=Math.sign(state.cosmicYears)*COSMIC_LIMIT;state.playing=false;syncPlayback();toast('Reached the illustrative model’s 500-million-year limit. Reverse or reset to continue.');}}
 galaxyView.update(state.cosmicYears,state.view==='cosmic',state.orbits,$('stars-toggle').checked);
 const target=galaxyView.target(state.follow);
 if(transition){const t=Math.min(1,(now-transition.start)/1600),ease=1-Math.pow(1-t,3),d=cameraDestination();camera.position.lerpVectors(transition.position,d.target.clone().add(d.offset),ease);controls.target.lerpVectors(transition.target,d.target,ease);if(t===1)transition=null;}else{const delta=target.sub(before);camera.position.add(delta);controls.target.add(delta);}
 controls.update();renderer.render(galaxyView.scene,camera);galaxyView.labels(camera,$('observatory').clientWidth,$('observatory').clientHeight,state.labels);
 if(now-lastUI>150){$('cosmic-time').textContent=(state.cosmicYears<0?'−':'+')+(Math.abs(state.cosmicYears)/1e6).toFixed(2)+' million years';$('distance').innerHTML=state.view==='cosmic'?galaxyView.motion.distanceLy.toLocaleString('en-US',{maximumFractionDigits:0})+' <small>light-years</small>':(((state.cosmicYears/GALACTIC_YEAR%1)+1)%1*100).toFixed(1)+' <small>%</small>';lastUI=now;}
}
$('play').onclick=()=>{state.playing=!state.playing;syncPlayback();};$('speed').onchange=e=>{if(isGalactic())state.cosmicSpeed=Number(e.target.value);else state.speed=Number(e.target.value);};$('reverse').onclick=()=>{state.direction=-1;$('reverse').classList.add('active');$('reverse').setAttribute('aria-pressed','true');};$('forward').onclick=()=>{state.direction=1;$('reverse').classList.remove('active');$('reverse').setAttribute('aria-pressed','false');};
$('now').onclick=()=>{if(isGalactic()){state.cosmicYears=0;galaxyView.update(0,state.view==='cosmic',state.orbits,$('stars-toggle').checked);focus(true);return;}state.time=Date.now();updatePositions();createOrbits();focus(true);};$('date').onchange=e=>{const t=Date.parse(e.target.value+'T12:00:00Z');if(!Number.isFinite(t)||t<MIN_TIME||t>MAX_TIME){toast('Choose a date between 1800 and 2050.');return;}state.time=t;updatePositions();createOrbits();focus(true);};
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>setView(button.dataset.view));document.querySelectorAll('[data-scale]').forEach(button=>button.onclick=()=>setView(button.dataset.scale));$('cosmic-frame').onchange=e=>{state.follow=e.target.value;focus();};
$('orbits-toggle').onclick=()=>{state.orbits=!state.orbits;$('orbits-toggle').classList.toggle('active',state.orbits);$('orbits-toggle').setAttribute('aria-pressed',String(state.orbits));};$('labels-toggle').onclick=()=>{state.labels=!state.labels;$('labels-toggle').classList.toggle('active',state.labels);$('labels-toggle').setAttribute('aria-pressed',String(state.labels));};
$('zoom-in').onclick=()=>{transition=null;camera.position.sub(controls.target).multiplyScalar(.8).add(controls.target);};$('zoom-out').onclick=()=>{transition=null;camera.position.sub(controls.target).multiplyScalar(1.25).add(controls.target);};$('reset-camera').onclick=()=>focus();
$('settings').onclick=()=>$('settings-dialog').showModal();document.querySelectorAll('.dialog-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('true-scale').onchange=e=>{state.trueScale=e.target.checked;lastTrailTime=NaN;updatePositions();createOrbits();focus(true);$('scale-note').textContent=state.trueScale?'PHYSICAL SIZES & DISTANCES':'SIZES & DISTANCES ENHANCED';toast(state.trueScale?'Physical scale enabled. Use the planet strip to get closer.':'Enhanced scale enabled.');};$('stars-toggle').onchange=e=>{stars.visible=e.target.checked;};$('atmosphere-toggle').onchange=e=>{state.atmospheres=e.target.checked;atmospheres.forEach(a=>a.visible=state.atmospheres);};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('observatory').requestFullscreen();}catch{toast('Fullscreen is unavailable in this browser view.');}};
function showAbout(){$('dialog-content').innerHTML='<span class="eyebrow">A LITTLE PERSPECTIVE</span><h2>A window into our neighborhood.</h2><p>Explore the Sun, all eight planets, and Earth’s Moon. Drag to orbit, scroll or pinch to zoom, and choose a planet below to follow it. Time can run forward or backward.</p><h3>Motion grounded in astronomy</h3><p>Planetary positions use JPL’s approximate Keplerian elements for 1800–2050. The Earth–Moon barycenter is corrected using a low-precision lunar orbit. Planet rotation periods and axial tilts are represented; surface orientation and weather are illustrative. Lighting is adjusted for visibility, and star positions are not a catalog.</p><h3>Space needs perspective</h3><p>Enhanced mode compresses orbital distances and enlarges bodies for exploration. Physical scale restores actual size and distance ratios. This is an educational visualization, not a navigation ephemeris or an N-body gravity simulation.</p><h3>Moving through the galaxy</h3><p>Galactic voyage traces the previous 540 days at an approximate 200 km/s around the Milky Way, using a locally straight path. The camera follows the Sun; the colored lines show earlier positions in the galactic frame. This short journey cannot show a full galactic orbit, which takes roughly 230 million years. Enhanced mode compresses the paths.</p><h3>The Milky Way, in motion</h3><p>Milky Way and Through space use a separate clock measured in millions of years. The Solar System marker orbits at 26,700 light-years from the center in approximately 230 million years. All its planets fit within that enlarged marker; choose one below to return to the planetary clock.</p><p>The galaxy is an illustrative barred spiral with approximate circular stellar orbits. Through space adds a constant drift of 620 km/s using the Local Group’s bulk motion relative to the cosmic microwave background (CMB), toward Galactic longitude 271.9° and latitude 29.6°. This approximates the Milky Way’s bulk motion, not its exact individual velocity. CMB is a reference frame, not absolute rest.</p><p>The galactic model omits gravity between galaxies, cosmic expansion, and future structural evolution. The grid and background points are reference markers, not mapped galaxies. Long time spans illustrate the hierarchy of motion rather than predict the galaxy’s future.</p><h3>Background music</h3><p><a href="https://pixabay.com/music/ambient-space-galaxy-universe-music-473849/" target="_blank" rel="noreferrer">Space Galaxy Universe Music — ViacheslavStarostin / Pixabay ↗</a><br><a href="https://pixabay.com/service/license-summary/" target="_blank" rel="noreferrer">Pixabay Content License ↗</a></p><h3>Sources & imagery</h3><p><a href="https://ssd.jpl.nasa.gov/planets/approx_pos.html" target="_blank" rel="noreferrer">NASA / JPL orbital elements ↗</a><br><a href="https://ssd.jpl.nasa.gov/planets/phys_par.html" target="_blank" rel="noreferrer">JPL planetary physical parameters ↗</a><br><a href="https://stjarnhimlen.se/comp/ppcomp.html" target="_blank" rel="noreferrer">Paul Schlyter’s approximate lunar model ↗</a><br><a href="https://science.nasa.gov/sun/facts/" target="_blank" rel="noreferrer">NASA: the Sun’s galactic journey ↗</a><br><a href="https://pdgweb.lbl.gov/2023/reviews/rpp2023-rev-cosmic-microwave-background.pdf" target="_blank" rel="noreferrer">Particle Data Group: CMB motion, §29.2 ↗</a><br><a href="https://www.solarsystemscope.com/textures/" target="_blank" rel="noreferrer">Planet textures: Solar System Scope / INOVE ↗</a><br><a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">Textures licensed under CC BY 4.0 ↗</a></p><p>Texture colors are enhanced and some unmapped terrain is filled artistically. The star field is illustrative.</p>';$('info-dialog').showModal();}
$('help').onclick=showAbout;$('model-info').onclick=showAbout;$('details').onclick=()=>{if(state.view==='solar'||state.view==='voyage'||isGalactic()){showAbout();return;}const b=bodies.find(b=>b.id===state.selected);$('dialog-content').innerHTML='<span class="eyebrow">'+b.category+'</span><h2>'+b.name+'</h2><p>'+b.detail+'</p><div class="detail-facts"><div><span>Mean radius</span><b>'+b.radius.toLocaleString()+' km</b></div><div><span>Axial tilt</span><b>'+b.tilt+'°</b></div></div><p>'+b.extra+'</p>';$('info-dialog').showModal();};
const raycaster=new THREE.Raycaster();let pointerStart=null;
renderer.domElement.addEventListener('pointerdown',e=>{pointerStart={x:e.clientX,y:e.clientY};});renderer.domElement.addEventListener('pointerup',e=>{if(isGalactic()||!ready||!pointerStart||Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>5)return;const rect=renderer.domElement.getBoundingClientRect();raycaster.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const hits=raycaster.intersectObjects(bodies.map(b=>planetObjects[b.id].mesh));if(hits.length){const b=bodies.find(b=>planetObjects[b.id].mesh===hits[0].object);selectBody(b.id);}});
renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();state.playing=false;syncPlayback();toast('The 3D view was interrupted. Reload the page to restore it.');});
window.addEventListener('resize',resize);document.addEventListener('keydown',e=>{if(/INPUT|SELECT|BUTTON|TEXTAREA/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;const key=e.key.toLowerCase();if(e.code==='Space'){e.preventDefault();$('play').click();}if(key==='r')focus();if(key==='o')$('orbits-toggle').click();if(key==='l')$('labels-toggle').click();});
async function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{await context.registerTool({name:'configure_observatory',description:'Select a planet or view, set a planetary date, and control playback. Speed is for planetary views; galacticYearsPerSecond controls the separate galactic clock.',inputSchema:{type:'object',properties:{body:{type:'string',enum:bodies.map(b=>b.id)},view:{type:'string',enum:['earth','solar','voyage','galaxy','cosmic']},date:{type:'string',description:'Date YYYY-MM-DD, from 1800 through 2050'},playing:{type:'boolean'},speed:{type:'number',enum:[1,3600,86400,604800,2592000]},galacticYearsPerSecond:{type:'number',enum:cosmicSpeeds}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('Expected an object');for(const key of Object.keys(input))if(!['body','view','date','playing','speed','galacticYearsPerSecond'].includes(key))throw new Error('Unknown option');if(input.body!==undefined&&!bodies.some(b=>b.id===input.body))throw new Error('Unknown celestial body');if(input.view!==undefined&&!['earth','solar','voyage','galaxy','cosmic'].includes(input.view))throw new Error('Unknown view');if(input.playing!==undefined&&typeof input.playing!=='boolean')throw new Error('playing must be boolean');if(input.speed!==undefined&&![1,3600,86400,604800,2592000].includes(input.speed))throw new Error('Unsupported speed');if(input.galacticYearsPerSecond!==undefined&&!cosmicSpeeds.includes(input.galacticYearsPerSecond))throw new Error('Unsupported galactic speed');let time;if(input.date!==undefined){if(typeof input.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(input.date))throw new Error('Invalid date');time=Date.parse(input.date+'T12:00:00Z');if(!Number.isFinite(time)||time<MIN_TIME||time>MAX_TIME||new Date(time).toISOString().slice(0,10)!==input.date)throw new Error('Date outside 1800–2050 or invalid');}if(time!==undefined){state.time=time;updatePositions();createOrbits();focus(true);}if(input.body)selectBody(input.body);if(input.view)setView(input.view);if(input.playing!==undefined){state.playing=input.playing;syncPlayback();}if(input.speed!==undefined){state.speed=input.speed;if(!isGalactic())$('speed').value=String(input.speed);}if(input.galacticYearsPerSecond!==undefined){state.cosmicSpeed=input.galacticYearsPerSecond;if(isGalactic())$('speed').value=String(state.cosmicSpeed);}await new Promise(resolve=>setTimeout(resolve,1700));return{elapsedGalacticYears:state.cosmicYears,galacticYearsPerSecond:state.cosmicSpeed,body:state.selected,view:state.view,date:new Date(state.time).toISOString(),playing:state.playing,speed:state.speed};}},{signal:lifecycle.signal});}catch(error){console.warn('Optional observatory tools could not register',error);}}
init().then(registerTools).catch(error=>{console.error(error);$('loading').innerHTML='<span>We couldn’t load the observatory.</span><small>Please check your connection and reload this page.</small><button onclick="location.reload()">Try again ↻</button>';});
